function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1) return 'mat needs at least one row.';
  const width = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (width < 1) return 'Each row needs at least one cell.';
  if (mat.length * width > 10000) return 'mat has at most 10000 cells.';
  let zeros = 0;
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== width) return 'All rows must have the same length.';
    for (const v of row) {
      if (v !== 0 && v !== 1) return 'Each cell is 0 or 1.';
      if (v === 0) zeros++;
    }
  }
  if (zeros === 0) return 'mat must contain at least one 0.';
  return null;
}

