function updateMatrix(mat) {
  // With no walls, the shortest walk between two cells is their Manhattan distance.
  const zeros = [];
  mat.forEach((row, i) => row.forEach((v, j) => { if (v === 0) zeros.push([i, j]); }));
  return mat.map((row, i) => row.map((v, j) => {
    let least = Infinity;
    for (const [zi, zj] of zeros) least = Math.min(least, Math.abs(zi - i) + Math.abs(zj - j));
    return least;
  }));
}

