function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  let rows, cols;
  if (size === 'large') {
    const shapes = [[100, 100], [100, 100], [50, 100], [100, 37], [1, 100], [100, 1]];
    [rows, cols] = shapes[pick(shapes.length)];
  } else {
    rows = 1 + pick(5);
    cols = 1 + pick(5);
  }
  const ones = [0.3, 0.6, 0.85, 0.97, 1][pick(5)];
  const mat = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < ones ? 1 : 0)));
  if (!mat.some(row => row.includes(0))) mat[pick(rows)][pick(cols)] = 0;
  return [mat];
}
